html:
{%- set hoc = frappe.db.get_value("Hire Order Contract", doc.hire_order_contract, ["customer_reference", "customer_reference_date", "project"], as_dict=True) if doc.hire_order_contract else None -%}
{%- set project_name = (frappe.db.get_value("Project", hoc.project, "project_name") if (hoc and hoc.project) else "") or (hoc.project if hoc else "") or "" -%}
{%- set lpo_date = frappe.utils.formatdate(hoc.customer_reference_date, "dd-mm-yyyy") if (hoc and hoc.customer_reference_date) else "" -%}
{%- set min_rows = 8 -%}
{%- set lines = doc.job_lines or [] -%}
<style>
	.jcr { font-family: Arial, Helvetica, sans-serif; font-size: 9pt; color: #000; }
	.jcr table { width: 100%; border-collapse: collapse; }
	.jcr td, .jcr th { border: 1px solid #000; padding: 5px 7px; vertical-align: middle; text-align: left; font-weight: normal; }
	.jcr .no-border td { border: none; }
	.jcr .jcr-no { text-align: right; color: #c00; letter-spacing: 3px; font-size: 10pt; margin: 4px 0 2px 0; }
	.jcr .jcr-title { display: inline-block; background: #000; color: #fff; font-size: 11pt; padding: 1px 3px; margin: 0; }
	.jcr .info td.label { width: 22%; }
	.jcr .info td { height: 15px; }
	.jcr .gap { height: 8px; border: none; }
	.jcr thead { display: table-header-group; }
	.jcr tr { page-break-inside: avoid; }
	.jcr .items th { height: 28px; }
	.jcr .items td { height: 38px; }
	.jcr .items .c { text-align: center; }
	.jcr .detail { color: #c00; }
	.jcr .sign td { width: 50%; vertical-align: top; height: 120px; padding-top: 4px; }
	.jcr .sign .head { font-weight: bold; text-decoration: underline; margin-bottom: 14px; }
	.jcr .sign .line { margin-bottom: 20px; }
</style>
<div class="jcr">
	<div class="jcr-no">JCR No. | {{ doc.name }}</div>
	<h4 class="jcr-title">Job Completion Report</h4>

	<table class="info">
		<tr><td class="label">Client Name</td><td>{{ doc.customer_name or doc.customer or "" }}</td></tr>
		<tr><td class="label">Project Name</td><td>{{ project_name }}</td></tr>
		<tr><td class="label">LPO No.</td><td>{{ (hoc.customer_reference if hoc else "") or "" }}</td></tr>
		<tr><td class="label">LPO Date</td><td>{{ lpo_date }}</td></tr>
	</table>
	<div class="gap"></div>

	<table class="items">
		<thead>
			<tr>
				<th class="c" style="width:6%">Sl. No.</th>
				<th>Job Description</th>
				<th style="width:9%">Qty.</th>
				<th style="width:8%">Unit</th>
				<th class="c" style="width:12%">Erection<br>(Date)</th>
				<th class="c" style="width:12%">Dismantling<br>(Date)</th>
			</tr>
		</thead>
		<tbody>
		{%- for row in lines %}
			<tr>
				<td class="c">{{ loop.index }}</td>
				<td>
					{{ row.job_type_name or row.job_type }}{% if row.location %} @ {{ row.location }}{% endif %}
					{%- if row.remarks %}<div class="detail">{{ (row.remarks or "") | e | replace("\n", "<br>" | safe) }}</div>{% endif %}
				</td>
				<td>{% if row.job_qty == (row.job_qty | int) %}{{ row.job_qty | int }}{% else %}{{ "%.2f" | format(row.job_qty) }}{% endif %}</td>
				<td>{{ frappe.db.get_value("Item", row.job_type, "stock_uom") or "" }}</td>
				<td class="c">{{ frappe.utils.formatdate(row.erection_date, "dd-mm-yyyy") if row.erection_date else "" }}</td>
				<td class="c">{{ frappe.utils.formatdate(row.dismantle_date, "dd-mm-yyyy") if row.dismantle_date else "" }}</td>
			</tr>
		{%- endfor %}
		{%- for i in range(lines | length, min_rows) %}
			<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td></tr>
		{%- endfor %}
		</tbody>
	</table>
	<div class="gap"></div>

	<table class="sign" style="page-break-inside: avoid;">
		<tr>
			<td>
				<div class="head">For M/s. {{ doc.company }}</div>
				<div class="line">Name:</div>
				<div class="line">Designation:</div>
				<div class="line">Mobile No.:</div>
				<div>Signature:</div>
			</td>
			<td>
				<div class="head">For Customer</div>
				<div class="line">Site (In charge) Name:</div>
				<div class="line">Designation:</div>
				<div class="line">Mobile No.:</div>
				<div>Signature:</div>
			</td>
		</tr>
	</table>
</div>
